SELECT CASE WHEN monthly_fee >= 214 THEN 'high' WHEN monthly_fee >= 72 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, SUM(monthly_fee) AS total_monthly_fee, ROUND(SUM(monthly_fee) * 100.0 / SUM(SUM(monthly_fee)) OVER (), 2) AS pct_of_total FROM subscriptions GROUP BY CASE WHEN monthly_fee >= 214 THEN 'high' WHEN monthly_fee >= 72 THEN 'mid' ELSE 'low' END ORDER BY total_monthly_fee DESC;
